function renderWordTable(highlight = []) {
  const tbody = document.getElementById('wtBody');
  if (!tbody) return;
  // highlight[i] = letter → index rule: [0,1,0]
  const idxRule = [0, 1, 0];
  tbody.innerHTML = Object.entries(WORD_TABLE).map(([letter, words]) => {
    const hi = highlight.indexOf(letter);  // -1 or 0,1,2
    const isHl = hi !== -1;
    const cells = words.map((w, i) => {
      // badge if this is the word selected for the phrase
      const badge = isHl && idxRule[hi] === i
        ? `<span class="wt-idx">${i}</span>` : '';
      return `<td>${w}${badge}</td>`;
    }).join('');
    return `<tr class="${isHl ? 'wt-hl' : ''}"><td>${letter}</td>${cells}</tr>`;
  }).join('');
}

